```json
{
  "steps": [
    {
      "task": "detect_spatial_columns",
      "player": "spatial_temporal_specialist",
      "rationale": "Detect spatial columns in the CSV to determine if spatialCoverage can be populated.",
      "outputs": [
        "spatial_detection"
      ]
    },
    {
      "task": "detect_temporal_columns",
      "player": "spatial_temporal_specialist",
      "rationale": "Detect temporal columns in the CSV to determine if temporalCoverage can be populated.",
      "outputs": [
        "temporal_detection"
      ]
    },
    {
      "task": "get_spatial_extent_from_tuple_column",
      "player": "spatial_temporal_specialist",
      "rationale": "Calculate spatial bounding box from detected tuple coordinate columns if present.",
      "inputs": {
        "spatial_detection": "spatial_detection"
      },
      "outputs": [
        "spatial_extent"
      ]
    },
    {
      "task": "get_spatial_extent",
      "player": "spatial_temporal_specialist",
      "rationale": "Calculate spatial bounding box from detected separate latitude and longitude columns if present.",
      "inputs": {
        "spatial_detection": "spatial_detection"
      },
      "outputs": [
        "spatial_extent_separate"
      ]
    },
    {
      "task": "get_temporal_extent",
      "player": "spatial_temporal_specialist",
      "rationale": "Calculate temporal extent from detected timestamp columns.",
      "inputs": {
        "temporal_detection": "temporal_detection"
      },
      "outputs": [
        "temporal_extent"
      ]
    },
    {
      "task": "compile_spatial_temporal_data",
      "player": "spatial_temporal_specialist",
      "rationale": "Combine all spatial and temporal extent results into a single artifact for the metadata generator.",
      "inputs": {
        "spatial_extent": "spatial_extent",
        "spatial_extent_separate": "spatial_extent_separate",
        "temporal_extent": "temporal_extent"
      },
      "outputs": [
        "spatial_temporal_data"
      ]
    },
    {
      "task": "generate_metadata",
      "player": "croissant_inaturalist_metadata_generator",
      "rationale": "Generate the final iNaturalist Croissant metadata with spatialCoverage and temporalCoverage from the compiled analysis.",
      "inputs": {
        "metadata_standard": "metadata_standard",
        "spatial_temporal": "spatial_temporal_data"
      },
      "outputs": [
        "metadata_output"
      ]
    }
  ]
}
```

